// CS2 skin data: rarities, odds, wear, prices in bottles, and the lazily loaded snapshot of real cases.
// The snapshot (src/content/skins/snapshot.json) is generated by scripts/fetch-skins.ts from ByMykel/CSGO-API
// and holds names, rarities, floats, StatTrak availability and colour palettes. No Valve images anywhere.

import { PALETTE_OVERRIDES, finishPalette } from './looks';

/** 2 Mil-Spec, 3 Restricted, 4 Classified, 5 Covert, 6 rare special item (★ knife or gloves). */
export type CsRarity = 2 | 3 | 4 | 5 | 6;

export const CS_RARITIES: CsRarity[] = [2, 3, 4, 5, 6];

/** Colours as in CS, plus a shape per tier so colour is never the only cue. */
export const CS_RARITY: Record<CsRarity, { name: string; short: string; color: string; icon: string }> = {
  2: { name: 'Mil-Spec', short: 'Mil-Spec', color: '#4b69ff', icon: '●' },
  3: { name: 'Restricted', short: 'Restricted', color: '#8847ff', icon: '▲' },
  4: { name: 'Classified', short: 'Classified', color: '#d32ce6', icon: '◆' },
  5: { name: 'Covert', short: 'Covert', color: '#eb4b4b', icon: '■' },
  6: { name: 'Rzadki przedmiot specjalny', short: '★', color: '#e4ae39', icon: '★' },
};

/** Case odds as in CS. A tier missing from a case gives its share to the tiers that are there. */
export const CASE_ODDS: Record<CsRarity, number> = { 2: 0.7992, 3: 0.1598, 4: 0.032, 5: 0.0064, 6: 0.0026 };
export const STATTRAK_CHANCE = 0.1;

export interface Wear {
  name: string;
  short: string;
  /** Upper float bound (exclusive, except Battle-Scarred). */
  max: number;
}

export const WEARS: Wear[] = [
  { name: 'Factory New', short: 'FN', max: 0.07 },
  { name: 'Minimal Wear', short: 'MW', max: 0.15 },
  { name: 'Field-Tested', short: 'FT', max: 0.38 },
  { name: 'Well-Worn', short: 'WW', max: 0.45 },
  { name: 'Battle-Scarred', short: 'BS', max: 1 },
];

/** Bottles. One bottle is 0,50 zł, so a case with its key costs 15 zł: two to four cases from a good run. */
export const SHOP = {
  casePrice: 10,
  keyPrice: 20,
  /**
   * Selling back to the recyklomat, by rarity, before wear and StatTrak™. Each tier is worth ten of the one
   * below, so a trade-up contract is roughly value-neutral; a case still pays back only about 3/4 of its price.
   */
  sell: { 2: 1, 3: 10, 4: 100, 5: 1000, 6: 3500 } as Record<CsRarity, number>,
  /** Factory New sells for more, Battle-Scarred for less. */
  wearMul: [1.35, 1.12, 1, 0.9, 0.8],
  stattrakMul: 1.6,
  /** Skins needed for one trade-up contract. */
  tradeUp: 10,
  /** Covert skins needed for a ★ contract (the CS2 rule since 2025). */
  tradeUpCovert: 5,
};

/** How many skins of this tier one contract takes. */
export const contractSize = (rarity: CsRarity): number => (rarity === 5 ? SHOP.tradeUpCovert : SHOP.tradeUp);

export interface SkinDef {
  id: string;
  /** Weapon key: ak47, knife_karambit, sporty_gloves. */
  weapon: string;
  pattern: string;
  phase?: string;
  rarity: CsRarity;
  finish: string;
  float: [number, number];
  stattrak: boolean;
  souvenir: boolean;
  collection?: string;
  palette: string[];
}

export interface CaseDef {
  id: string;
  name: string;
  date: string;
  items: SkinDef[];
  rare: SkinDef[];
}

export interface SkinDb {
  fetched: string;
  weaponNames: Record<string, string>;
  cases: CaseDef[];
  collections: Map<string, string>;
  skins: Map<string, SkinDef>;
  /** Weapon skins of each collection, the pool a trade-up draws from. */
  byCollection: Map<string, SkinDef[]>;
  /** Cases a collection's skins come from (★ trade-ups draw from their rare pools). */
  casesOf: Map<string, CaseDef[]>;
}

export interface RawSnapshot {
  fetched: string;
  weapons: Record<string, string>;
  cases: { id: string; name: string; date: string; items: string[]; rare: string[] }[];
  collections: { id: string; name: string }[];
  skins: Record<string, { w: string; p: string; ph?: string; r: number; s: string; f: [number, number]; st: 0 | 1; sv: 0 | 1; c?: string; pal: string[] }>;
}

export function buildDb(raw: RawSnapshot): SkinDb {
  const skins = new Map<string, SkinDef>();
  for (const [id, s] of Object.entries(raw.skins)) {
    const key = `${raw.weapons[s.w] ?? s.w} | ${s.p}`;
    const palette = PALETTE_OVERRIDES[key] ?? finishPalette(s.s, s.p, s.ph) ?? (s.pal.length ? s.pal : ['#8a8f99', '#5b616b', '#c9ced6']);
    skins.set(id, {
      id,
      weapon: s.w,
      pattern: s.p,
      ...(s.ph ? { phase: s.ph } : {}),
      rarity: Math.min(6, Math.max(2, s.r)) as CsRarity,
      finish: s.s,
      float: s.f,
      stattrak: s.st === 1,
      souvenir: s.sv === 1,
      ...(s.c ? { collection: s.c } : {}),
      palette,
    });
  }
  const pick = (ids: string[]): SkinDef[] => ids.map((i) => skins.get(i)).filter((s): s is SkinDef => s !== undefined);
  const cases = raw.cases.map((c) => ({ id: c.id, name: c.name, date: c.date, items: pick(c.items), rare: pick(c.rare) }));
  const byCollection = new Map<string, SkinDef[]>();
  for (const s of skins.values()) {
    if (!s.collection) continue;
    const list = byCollection.get(s.collection) ?? [];
    list.push(s);
    byCollection.set(s.collection, list);
  }
  const casesOf = new Map<string, CaseDef[]>();
  for (const c of cases) {
    for (const s of c.items) {
      if (!s.collection) continue;
      const list = casesOf.get(s.collection) ?? [];
      if (!list.includes(c)) list.push(c);
      casesOf.set(s.collection, list);
    }
  }
  return { fetched: raw.fetched, weaponNames: raw.weapons, cases, collections: new Map(raw.collections.map((c) => [c.id, c.name])), skins, byCollection, casesOf };
}

let loading: Promise<SkinDb> | null = null;

/**
 * The snapshot is a separate chunk: it loads when the hub first needs it, not with the game. It comes in as
 * text and is parsed here, which also spares the type checker from inferring a type for 300 kB of JSON.
 */
export function loadSkinDb(): Promise<SkinDb> {
  loading ??= import('./snapshot.json?raw').then((m) => buildDb(JSON.parse(m.default) as RawSnapshot));
  return loading;
}

/** "AK-47 | Redline", "★ Karambit | Doppler (Phase 2)", "★ Karambit". */
export function skinName(db: SkinDb, s: SkinDef): string {
  const weapon = db.weaponNames[s.weapon] ?? s.weapon;
  const star = s.rarity === 6 ? '★ ' : '';
  if (!s.pattern) return `${star}${weapon}`;
  return `${star}${weapon} | ${s.pattern}${s.phase ? ` (${s.phase})` : ''}`;
}

export function wearOf(float: number): Wear {
  return WEARS.find((w) => float < w.max) ?? WEARS[WEARS.length - 1];
}

export function wearIndex(float: number): number {
  return WEARS.indexOf(wearOf(float));
}
